css:
@keyframes fxhs-up{from{transform:translateY(112%) rotate(2deg)}to{transform:none}}@keyframes fxhs-fade{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:none}}
.fx-hsr{width:min(940px,100%);display:grid;gap:1.6em;justify-items:start}
.fx-hsr .eye{font-size:.78em;font-weight:700;letter-spacing:.18em;text-transform:uppercase;color:var(--accent);animation:fxhs-fade calc(.7s/var(--speed)) both}
.fx-hsr h2{font-size:clamp(2.4em,7vw,5.6em);line-height:1.04;letter-spacing:-.02em}
.fx-hsr .ln{display:block;overflow:hidden;padding:.08em 0 .16em;margin:-.08em 0 -.16em}
.fx-hsr .ln>span{display:block;transform-origin:left bottom;animation:fxhs-up calc(1s/var(--speed)) cubic-bezier(.2,.8,.2,1) both;animation-delay:calc(.1s + var(--i)*130ms/var(--speed))}
.fx-hsr em{font-style:italic;color:var(--primary)}
.fx-hsr .sub{max-width:34em;opacity:.72;font-size:1.12em;animation:fxhs-fade calc(.9s/var(--speed)) .7s both}
.fx-hsr .rp{all:unset;box-sizing:border-box;cursor:pointer;padding:.55em 1.1em;border:1px solid var(--border);border-radius:999px;font:700 .85em var(--font-body);animation:fxhs-fade calc(.9s/var(--speed)) .9s both;transition:background .2s}
.fx-hsr .rp:hover{background:color-mix(in srgb,var(--text) 6%,transparent)}.fx-hsr .rp:focus-visible{outline:2px solid var(--accent);outline-offset:3px}
.fx-hsr.rst *{animation:none!important}
@media(prefers-reduced-motion:reduce){.fx-hsr *{animation:none!important}}
/* touch: :hover mirrored as .is-tap */
.fx-hsr .rp.is-tap{background:color-mix(in srgb,var(--text) 6%,transparent)}
